---@return table[], table<number, table>, integer @ 结果数据列表, 品质分类map, 最高品质
function GachaponUtils.CalcGachaponResult(rewards)
    local rewardCardResult = {}
    local statistic = {}
    local rewardTopRare = 1
    local list = table.values(rewards)

    -- 1. fill rewardCardResult
    -- 2. count statistic (only card)
    -- 3. equle rewardTopRare
    for i = 1 , #list do
        local idType = GoodsUtils.GetIdType(list[i].goodsId)
        if idType == Constants.IDType.CharacterCard then
            local cardVo = CardConfMgr:GetInstance():GetCardByRefId(list[i].goodsId)
            if cardVo == nil then
                printInfo("%d not found", list[i].goodsId)
            end
            --list[i].animation = cardVo.animation
            if not isSet(statistic, cardVo.rare) then
                statistic[cardVo.rare] = { cnt = 0, cardIndexes = {} }
            end
            local tb = statistic[cardVo.rare]
            tb.cnt = tb.cnt + 1
            table.insert(tb.cardIndexes, i)

            rewardTopRare = Mathf.Max(rewardTopRare, cardVo.rare)

        else
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(list[i].goodsId)
            if goodsVo == nil then
                printInfo("%d not found", list[i].goodsId)
            end
            list[i].typeID = idType
            local num = GoodsUtils.GetThingNo(list[i].goodsId)
            list[i].isNew = num == 0
            if  idType == Constants.IDType.EquipmentCore then
                rewardTopRare = Mathf.Max(rewardTopRare, goodsVo.quality)
            end
        end
        table.insert(rewardCardResult, list[i])
    end
--[[
    ---@type table @ { stage1:integer, stage2:integer, stage3:integer, weight:integer }
    local stageRandom = nil
    if next(statistic) then
        local randRare = rewardTopRare
        if rewardTopRare == Constants.RareType.SSR and statistic[rewardTopRare].cnt > 1 then
            randRare = Constants.RareType.UR
        end
        local tbStage = GachaponShared._gachaponStage == nil and GachaponConstants.StageQuality or GachaponShared._gachaponStage
        if isSet(tbStage, randRare) then
            ---@type table[] @ { { stage1:integer, stage2:integer, stage3:integer, weight:integer }, ... }
            local arr = tbStage[randRare]
            -- total weight
            local sum = 0
            for i = 1, #arr do
                sum = sum + arr[i].weight
            end
            -- random weight
            local rand = math.random(sum)
            printInfo("stageRandomNum %d", rand)
            local tmp = nil
            for i = 1, #arr do
                if rand <= arr[i].weight then
                    tmp = i
                    break
                end
                rand = rand - arr[i].weight
            end
            if tmp == nil then
                printError("rand fail top rare %d", randRare)
            else
                printInfo("stageRandom %s", table.dump(arr[tmp]))
                stageRandom = arr[tmp]
            end
        end
    end
]]
    return rewardCardResult, statistic, rewardTopRare
end

