function GachaponUtils.GetAnimCurve(keyframes)
    assert(type(keyframes) == 'table')
    local keyFrame = CS.UnityEngine.Keyframe
    --print(table.dump(keyFrame))
    local animCurve = CS.UnityEngine.AnimationCurve
    --print(table.dump(animCurve))
    local result = animCurve()
    for i = 1, #keyframes do
        local param = keyframes[i]
        local key = keyFrame(param.time, param.value, param.inTangent, param.outTangent)
        --table.insert(csKeyframs, key)
        result:AddKey(key)
    end
    

    return result
end

