---@param director UnityEngine.Playables.PlayableDirector
---@param trackName string
---@param object UnityEngine.Object
---@return UnityEngine.Object[]
function GachaponUtils.BindTimeline(director, trackName, object)
    ---@type UnityEngine.Playables.PlayableBinding[]
    local list = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
    list:AddRange(director.playableAsset.outputs)
    --printInfo(director.playableAsset)
    --printInfo(dic)
    local cached = {}
    for i = 0, list.Count - 1 do
        if list[i].streamName == trackName then
            director:SetGenericBinding(list[i].sourceObject, object)
            table.insert(cached, list[i].sourceObject)
        end
    end

    list:Clear()
    return cached
end

---@param director UnityEngine.Playables.PlayableDirector
---@param trackName string
---@param eachAssetCB fun(clip:UnityEngine.Timeline.TimelineClip):void
function GachaponUtils.EachTimelineAnimationClips(director, trackName, eachCB)
    ---@type UnityEngine.Playables.PlayableBinding[]
    local bindList = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
    bindList:AddRange(director.playableAsset.outputs)

    for bindIndex = 0, bindList.Count - 1 do
        if bindList[bindIndex].streamName == trackName then
            ---@type UnityEngine.Timeline.AnimationTrack
            local animTrack = bindList[bindIndex].sourceObject
            local animClips = animTrack:GetClips()
            ---@type UnityEngine.Timeline.TimelineClip[]
            local clipList = support.new_list(typeof(CS.UnityEngine.Timeline.TimelineClip))
            clipList:AddRange(animClips)
            for clipIndex = 0, clipList.Count - 1 do
                -- print(clipList[clipIndex], clipList[clipIndex].asset, clipList[clipIndex].asset:GetType())
                if eachCB then
                    local clip = clipList[clipIndex]
                    eachCB(clip)
                end
            end
            clipList:Clear()
        end
    end

    bindList:Clear()
end

--- BindTimelines
---@param director UnityEngine.Playables.PlayableDirector
---@param trackName2object table<string, UnityEngine.Object>
---@return UnityEngine.Object[]
function GachaponUtils.BindTimelines(director, trackName2object, bindSuccessCb)
    ---@type UnityEngine.Playables.PlayableBinding[]
    local list = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
    list:AddRange(director.playableAsset.outputs)
    --printInfo(director.playableAsset)
    --printInfo(dic)
    local cached = {}
    for i = 0, list.Count - 1 do
        local streamName = list[i].streamName
        local object = trackName2object[streamName]
        if not isNull(object) then
            director:SetGenericBinding(list[i].sourceObject, object)
            table.insert(cached, list[i].sourceObject)
            if bindSuccessCb then
                bindSuccessCb(streamName, object)
            end
        end
    end

    list:Clear()
    return cached
end

