---@param director UnityEngine.Playables.PlayableDirector
---@param trackName string
---@param mute boolean
function GachaponUtils.SetRootTrackMute(director, trackName, mute)
    local trackNameList = string.split2(trackName, "/")
    local trackNameRoot = trackNameList[1]
    --List<TrackAsset> trackAssets = new List<TrackAsset>(asset.GetRootTracks());
    local list = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    list:AddRange(director.playableAsset:GetRootTracks())
    
    --printInfo(trackNameRoot)
    for i = 0, list.Count - 1 do
        if list[i].name == trackNameRoot then
            --printInfo(mute)
            if #trackNameList > 1 then
                GachaponUtils.SetSubTrackMute(list[i], trackNameList, mute, 2)
            else
                list[i].muted = mute
            end
            break
        end
    end
    list:Clear()
end

---@param trackAsset UnityEngine.Timeline.TrackAsset
---@param trackNameList string[]
---@param mute boolean
function GachaponUtils.SetSubTrackMute(trackAsset, trackNameList, mute, subLevel)
    local tracksLen = #trackNameList
    local trackName = trackNameList[subLevel]
    --List<TrackAsset> trackAssets = new List<TrackAsset>(asset.GetRootTracks());
    local list = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    list:AddRange(trackAsset:GetChildTracks())
    
    --printInfo(trackName)
    for i = 0, list.Count - 1 do
        if list[i].name == trackName then
            --printInfo(mute)
            if tracksLen == subLevel then
                list[i].muted = mute
            else
                GachaponUtils.SetSubTrackMute(list[i], trackNameList, mute, subLevel + 1)
            end
            break
        end
    end
    list:Clear()
end

---@param director UnityEngine.Playables.PlayableDirector
---@param trackName string
---@param mute boolean
function GachaponUtils.SetOutputTrackMute(director, trackName, mute)
    local list = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    list:AddRange(director.playableAsset:GetOutputTracks())

    --printInfo(trackName)
    for i = 0, list.Count - 1 do
        if list[i].name == trackName then
            --printInfo(mute)
            list[i].muted = mute
            break
        end
    end
    list:Clear()
end

---@param pool GachaponDojo
function GachaponUtils.IsPoolValid(pool)
    local activityData = checkTable(pool.activity)
    if GachaponUtils.IsOverseaStepType(pool.poolType) then
        if activityData.stepNum > activityData.totalStepNum then
            return false
        end
    elseif pool.poolType == GachaponConstants.PoolType.OverseaOnceNovice then
        return checkInt(activityData.noviceOverNum) < checkInt(activityData.noviceTotalNum)
    elseif GachaponUtils.IsOverseaCoronaType(pool.poolType) then
        return false
    else
        if pool.maxTimes ~= -1 and pool.callTimes >= pool.maxTimes then
            return false
        end
    end
    return true 
end

---@param pool GachaponDojo
---@return integer[]
function GachaponUtils.GetPoolCurrencyList(pool)
    local currencyLisst  = {}

    if serverDifferenceMgr:IsSecondaryCurrencyEnable() then
        local primaryCurrencyId   = checkInt(checkTable(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 17)).num)
        local secondaryCurrencyId = checkInt(checkTable(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 19)).num)
        if not table.indexof(currencyLisst, primaryCurrencyId) then
            table.insert(currencyLisst, primaryCurrencyId)
        end
        if not table.indexof(currencyLisst, secondaryCurrencyId) then
            table.insert(currencyLisst, secondaryCurrencyId)
        end
    end
    if checkInt(pool.ifDoubleCorn) > 0  then
        table.insert(currencyLisst, checkInt(pool.ifDoubleCorn))
    end

    if checkInt(pool.oneConsume.goodsId) > 0 then
        if not table.indexof(currencyLisst, checkInt(pool.oneConsume.goodsId)) then
            table.insert(currencyLisst, checkInt(pool.oneConsume.goodsId))
        end
    end
    
    if checkInt(pool.tenConsume.goodsId) > 0 then
        if not table.indexof(currencyLisst,  checkInt(pool.tenConsume.goodsId)) then
            table.insert(currencyLisst, checkInt(pool.tenConsume.goodsId))
        end
    end
    
    if GachaponUtils.IsOverseaLightDarkType(pool.poolType) then
        table.insert(currencyLisst, 1, Constants.Currency.LightDarkCoin)
    end
    return currencyLisst
end

---@param pool GachaponDojo
---@param type GachaponConstants.CallType @ 抽卡类型：1 单抽 type 2 十连
---@param activityData table | nil
---@generic V
---@param onSuccessCall fun(response:V)
function GachaponUtils.CallGachapon(pool, type, activityData, onSuccessCall)
    local goodsConfMgr = GoodsConfMgr:GetInstance()

    local isFreeCall = false
    if pool.freeData then
        local freeTimes = type == GachaponConstants.CallType.One and pool.freeData.oneLeftTimes or 0
        isFreeCall = freeTimes > 0
    end
    local consume = type == GachaponConstants.CallType.One and pool.oneConsume or pool.tenConsume
    local id = consume.goodsId
    local reqNum = consume.num
    local own = GoodsUtils.GetThingNo(id)
    local comp = GachaponUtils.GetGachaponComp()
    
    local goGachapon = function(leftParam, rightParm)
        local interfaces = Interfaces.CallGo
        local requestData = {poolId = pool.poolId, type = type}
        if activityData then
            interfaces = Interfaces.ActivityCall
            requestData.activityUuid = activityData.activityUuid
            requestData.camp         = activityData.camp
        end
        local comp = GachaponUtils.GetGachaponComp()
        comp.callActivityArgs = activityData
        GameUtils.Request(interfaces, requestData, function(request, response)
            --printInfo("test %s", jsonStr)
            if checkNumber(response.errCode) == 0 then
                --local gachaponUtils = import('Game.Gachapon.GachaponUtils')
                --local comp = gachaponUtils.GetGachaponComp()
                --comp:GetGachapon(response.data)
                local lastSSRNum = 0 
                local KTool = CS.Engine.Lib.KTool 
                if KTool.IsMobile() then
                    local ownerStr = "OWNER_SSR_NUM"
                    lastSSRNum = checkInt(CfUtils.GetLocalData(ownerStr , 0)) 
                    if lastSSRNum < 10 then
                        ---@type CardComponent
                        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                        lastSSRNum = comp:GetSRRCount()
                        CfUtils.WriteLocalData(ownerStr ,lastSSRNum)
                    end
                end
                local goodsRewards = checkTable(response.data.rewards)
                if not GachaponUtils.IsNewComerType(pool.poolType) then
                    GoodsUtils.DrawRewards(goodsRewards)
                    -- if checkInt(pool.poolType) == GachaponConstants.PoolType.PointNum then
                    --     local getGachaponConf = GachaponUtils.GetGachaponById(pool.poolId)
                    --     --- 更新活动点数
                    --     GoodsUtils.DrawRewards({
                    --         [1] = {
                    --             num = checkInt(response.data.activityPoint),
                    --             goodsId = getGachaponConf.singleCoin,
                    --         }
                    --     })
                    -- end
                end

                local consumes = response.data.consume

                if reqNum > own and not GachaponUtils.IsEquipType(pool.poolType) then
                    for k, consume in ipairs(consumes) do 
                        if rightParm and next(rightParm) ~= nil and rightParm.goodsId then
                            if checkInt(consume.goodsId) == checkInt(rightParm.goodsId) then
                                consume.num = reqNum - rightParm.num
                            end
                        end
                    end
                end

                -- 更新 getSSRTimes 的剩余次数
                if GachaponUtils.IsOverseaCampType(pool.poolType) then
                    local getSSRTimes = checkInt(response.data.getSSRTimes)
                    local campsGetSSRTimes = checkTable(pool.activity).campsGetSSRTimes or {}
                    -- 说阵营卡池是共享ssr次数，所以每个阵营子卡池一起更新次数
                    for campId, _ in pairs(campsGetSSRTimes) do
                        campsGetSSRTimes[campId] = getSSRTimes
                    end
                elseif GachaponUtils.IsOverseaStepType(pool.poolType) then
                    pool.activity.stepNum = pool.activity.stepNum + 1
                    pool.tenConsume.goodsId = response.data.nextConsume.goodsId
                    pool.tenConsume.num = response.data.nextConsume.num
                else
                    if pool.getSSRTimes then
                        pool.getSSRTimes = checkInt(response.data.getSSRTimes)
                    end
                end

                -- 额外的福袋奖励
                local extraRewards = checkTable(response.data.extraRewards)
                local luckyBagRewards = checkTable(response.data.luckyBagRewards)
                table.insertto(extraRewards, luckyBagRewards)
                if #extraRewards > 0 then
                    GoodsUtils.DrawRewards(extraRewards, true)
                end
                local KTool = CS.Engine.Lib.KTool 
                if KTool.IsMobile() then
                    if lastSSRNum < 10 then
                        local ownerStr = "OWNER_SSR_NUM"
                        local uploadSSRNums = {1, 5 ,10}
                        ---@type CardComponent
                        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                        local currentSSRNum = comp:GetSRRCount()
                        for i = # uploadSSRNums , 1, -1 do
                            local num = uploadSSRNums[i]
                            if lastSSRNum < num and  currentSSRNum >= num then
                                ---@type PlayerComponent
                                local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                                xRecord.af_internal("role_ssr" .. num)
                                CfUtils.WriteLocalData(ownerStr ,currentSSRNum)
                                break
                            end
                        end
                    end
                end

                -- 更新海外新手抽卡 已十连次数
                if checkInt(pool.poolType) == GachaponConstants.PoolType.OverseaOnceNovice then
                    pool.activity.noviceOverNum = pool.activity.noviceOverNum + 1
                end

                -- 是否有免费次数
                if isFreeCall then
                    GachaponUtils.ConsumeFreeCallTimes(pool.poolId, type)
                else
                    -- 扣除抽卡消耗
                    GoodsUtils.ConsumeGoods(consumes, true)
                    -- 因为可能几个卡池的消耗是相同的，所以这里需要全卡池检测一遍
                    GachaponUtils.CheckConsumeEnoughRedPoint()
                end

                -- 更新已抽卡次数
                comp:CallsPoolById(pool.poolId, type, goodsRewards)

                if #goodsRewards > 0 then
                    if onSuccessCall ~= nil then
                        onSuccessCall(response)
                    end
                else
                    GameUtils.Toast(localize('您抽了个寂寞'))
                end
                
            end
        end)
    end

    -- 是否需要检测抽卡消耗
    if isFreeCall == false and comp:WillConsume(pool) then
        if reqNum > own then
            local goodsVo = goodsConfMgr:GetGoodsVoById(id)
            local function GoJumpAway()
                if #checkTable(goodsVo.jumpAway) > 0 then
                    GoodsUtils.CheckConsumeDataCondition({{goodsId = id, num = reqNum, gainNum = reqNum - own}})
                else
                    GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
                end
            end
            if checkInt(pool.ifDoubleCorn) > 0 then
                local isPop , convertNum,  consumeData =  GachaponUtils.GetGachaponActvityIsPopAndConsumeData(id , reqNum , own)
                if not isPop then
                    return goGachapon()
                else 
                    local data = {
                        leftData = consumeData,
                        rightId = id,
                        rightNum = convertNum,
                        onConfirmClick = function()
                            CfUtils.DialogBack()
                            goGachapon()
                        end,
                    }
                    serverDifferenceMgr:OpenCurrencyExchangePopup(data)    
                end
            elseif not GachaponUtils.IsOverseaFriendshipType(pool.poolType) and serverDifferenceMgr:IsSecondaryCurrencyEnable() then
                local consumeId, consumeRatio = GachaponUtils.GetGachaponConsumeItemPrice(id)
                if consumeId == nil then
                    GoJumpAway()
                else
                    local needNum = reqNum - own
                    local minExchangeNum = GachaponUtils.GetGachaponExchangeMinNum(id)
                    needNum = math.ceil(needNum / minExchangeNum) * minExchangeNum
                    local consumeNum = math.ceil(consumeRatio * (needNum))
                    ---@type CommonCurrencyExchangePopup.InputData
                    local data = {
                        leftId = consumeId,
                        leftNum = consumeNum,
                        rightId = id,
                        rightNum = needNum,
                        onConfirmClick = goGachapon,
                    }
                    serverDifferenceMgr:OpenCurrencyExchangePopup(data)    
                end
            else
                GoJumpAway()
            end
        else
            goGachapon()
        end
    else
        goGachapon()
    end
    
end
---获取抽卡道具价格
---@return number,number  消耗货币id，消耗货币数量
function GachaponUtils.GetGachaponActvityIsPopAndConsumeData(activityGoodsId , reqNum ,  ownerNum)
    activityGoodsId = checkInt(activityGoodsId)
    ---@type GachaponActivityExChangeVo[]
    local vos = CfUtils.GetWholeVo(AutoIds.IdSetting6720,"GachaponActivityExChangeVo")
    ---@type GachaponActivityExChangeVo[]
    local poolVos = {}
    for k, v in ipairs(vos) do
        if v.getItemId == activityGoodsId then
            if v.itemId == Constants.Currency.PayDiamondId  then
                ---@type ServerDifferenceMgr
                local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
                if ServerDifferenceMgr:IsSecondaryCurrencyEnable() then
                    poolVos[#poolVos +1] = v     
                end
            else
                poolVos[#poolVos +1] = v     
            end
        end
    end
    table.sort(poolVos , function(a,b)
        return a.sort > b.sort 
    end)
    local needNum = reqNum - ownerNum
    local needOtherGoodsConsume = {}
    local oneNeedNum = needNum
    local count = #poolVos
    local convertNum = 0
    for k, v in ipairs(poolVos) do
        if count == k then
            local realUseNum = math.ceil(oneNeedNum / v.getItemNum) * v.itemNum
            convertNum = convertNum + math.ceil(oneNeedNum / v.getItemNum) * v.getItemNum
            needOtherGoodsConsume[#needOtherGoodsConsume+1] = { goodsId = v.itemId, num = realUseNum}
        else
            -- 获取当前转换道具的数量
            local currentGoodNum = GoodsUtils.GetThingNo(v.itemId)
            if currentGoodNum > 0 then
                -- 可以转化的份数
                local onePart =  math.floor(currentGoodNum/v.itemNum)
                if onePart > 0 then
                    -- 可以转化适应的道具
                    local canUserNum = onePart * v.itemNum
                    -- 可以转化道具数量和
                    local canConvertNum =  onePart * v.getItemNum
                    -- 如果拥有当前道具
                    if canConvertNum >= oneNeedNum then
                        local realUseNum = math.ceil(oneNeedNum / v.getItemNum) * v.itemNum
                        convertNum = convertNum + math.ceil(oneNeedNum / v.getItemNum) *  v.getItemNum
                        needOtherGoodsConsume[#needOtherGoodsConsume+1] = { goodsId = v.itemId, num = realUseNum}
                        break 
                    else
                        oneNeedNum = oneNeedNum - canConvertNum
                        convertNum = convertNum + canConvertNum
                        needOtherGoodsConsume[#needOtherGoodsConsume+1] = { goodsId = v.itemId, num = canUserNum}
                    end
                end 
            end
        end
    end
    local isPopEx = true
    if #needOtherGoodsConsume == 1 and  needOtherGoodsConsume[1].goodsId == poolVos[1].itemId then
        isPopEx = false 
    else 
        isPopEx = true
    end
    return isPopEx , convertNum , needOtherGoodsConsume
end

---获取抽卡道具价格
---@return number,number  消耗货币id，消耗货币数量
function GachaponUtils.GetGachaponConsumeItemPrice(goodsId)
    ---@type GachaponConsumePriceVo[]
    local vos = CfUtils.GetCf(AutoIds.IdSetting381,"GachaponConsumePriceVo",true)
    
    for i = 1, #vos do
        if vos[i].getItemId == goodsId then
            return vos[i].itemId, vos[i].itemNum / vos[i].getItemNum
        end
    end
    
    printInfo("抽卡道具兑换表  未找到 goodsId %d", goodsId)
    return nil
end

---@return number 最小兑换数量
function GachaponUtils.GetGachaponExchangeMinNum(goodsId)
    ---@type GachaponConsumePriceVo[]
    local vos = CfUtils.GetCf(AutoIds.IdSetting381,"GachaponConsumePriceVo",true)
    
    for i = 1, #vos do
        if vos[i].getItemId == goodsId then
            return vos[i].getItemNum
        end
    end
    
    printError("抽卡道具兑换表  未找到 goodsId %d", goodsId)
    return 1
end


function GachaponUtils.CheckRedPoint()
    GachaponUtils.CheckFreeCallRedPoint()
    GachaponUtils.CheckConsumeEnoughRedPoint()
end


--- 检测是否有免费抽次数
function GachaponUtils.CheckFreeCallRedPoint()
    local hasFreeCallRed = false
    for poolId, _ in pairs(GachaponUtils.GetGachaponComp():GetConsumeDataMap()) do
        if GachaponUtils.CheckFreeCallRedPointBy(poolId) then
            hasFreeCallRed = true
            break
        end
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.GachaponHasFreeCall, hasFreeCallRed and 1 or 0)
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.GachaponHasFreeCall)
end


---@param poolId integer
---@param callType GachaponConstants.CallType | nil
---@return boolean
function GachaponUtils.CheckFreeCallRedPointBy(poolId, callType)
    local poolConsumeData = GachaponUtils.GetGachaponComp():GetConsumeDataMap()[checkInt(poolId)]
    if poolConsumeData and poolConsumeData.freeData then
        ---@type GachaponFreeDojo
        local callFreeData = poolConsumeData.freeData
        local oneFreeTimes = checkInt(callFreeData.oneLeftTimes)
        local tenFreeTimes = 0
        if callType == GachaponConstants.CallType.One then
            return oneFreeTimes > 0
        elseif callType == GachaponConstants.CallType.Ten then
            return tenFreeTimes > 0
        else
            return oneFreeTimes > 0 or tenFreeTimes > 0
        end
    else
        return false
    end
end


--- 消耗免费抽次数
---@param poolId integer
---@param callType GachaponConstants.CallType | nil
function GachaponUtils.ConsumeFreeCallTimes(poolId, callType)
    local consumeGroupId  = 0
    local poolConsumeData = GachaponUtils.GetGachaponComp():GetConsumeDataMap()[checkInt(poolId)]
    if poolConsumeData and poolConsumeData.freeData then
        ---@type GachaponFreeDojo
        local callFreeData = poolConsumeData.freeData
        consumeGroupId = checkInt(callFreeData.freeGroupId)
    end
    if consumeGroupId > 0 then
        for _, poolConsumeData in pairs(GachaponUtils.GetGachaponComp():GetConsumeDataMap()) do
            if poolConsumeData and poolConsumeData.freeData then
                ---@type GachaponFreeDojo
                local callFreeData = poolConsumeData.freeData
                -- 同组的 次数统一扣除
                if checkInt(callFreeData.freeGroupId) == consumeGroupId then
                    if callType == GachaponConstants.CallType.One then 
                        -- 扣除次数
                        callFreeData.oneLeftTimes = callFreeData.oneLeftTimes - 1
                        -- 重置时间
                        if callFreeData.oneLeftTimes <= 0 then
                            callFreeData:SetOneLeftSeconds(callFreeData.oneResetSeconds)
                        end
                    elseif callType == GachaponConstants.CallType.Ten then 
                    end
                end
            end
        end
    end
    -- 更新红点
    GachaponUtils.CheckFreeCallRedPoint()
end


--- 检测 全卡池抽卡道具是否足够
function GachaponUtils.CheckConsumeEnoughRedPoint()
    local hasConsumeEnoughRed = false
    for poolId, _ in pairs(GachaponUtils.GetGachaponComp():GetConsumeDataMap()) do
        if GachaponUtils.CheckConsumeEnoughRedPointBy(poolId) then
            hasConsumeEnoughRed = true
            break
        end
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.GachaponConsumeEnough, hasConsumeEnoughRed and 1 or 0)
end


--- 检测 指定卡池 抽卡道具是否足够
---@param poolId integer
---@return boolean
function GachaponUtils.CheckConsumeEnoughRedPointBy(poolId)
    local poolConsumeData = GachaponUtils.GetGachaponComp():GetConsumeDataMap()[checkInt(poolId)]
    if poolConsumeData then
        local poolType = checkInt(poolConsumeData.poolType)
        -- 现在又要改成红球的卡池不提示，所以走表里配置是否提示了 by 陈菲 2024/08/10
        -- if GachaponUtils.IsOverseaProgressType(poolType) or GachaponUtils.IsOverseaOptionalUpType(poolType) then
        --     return false  -- 活动卡池又要求去掉，满足十连抽的道具红点提示 by 陈菲 2024/06/14
        -- end
        local tenConsumeData = checkTable(poolConsumeData.tenConsume)
        local tenConsumeId   = checkInt(tenConsumeData.goodsId)
        local tenConsumeNum  = checkInt(tenConsumeData.num)
        local isOpenTenRed   = checkInt(poolConsumeData.isOpenTenRed) == 1
        local hasGodosNum    = GoodsUtils.GetThingNo(tenConsumeId)
        return isOpenTenRed and hasGodosNum >= tenConsumeNum
    else
        return false
    end
end


