function GachaponUtils.GetCoreVoByData(dojo)
    local settingId
    local voName
    if dojo.typeID == Constants.IDType.EquipmentCore then
        settingId = AutoIds.IdSetting106
        voName = "EquipCoreVo"
    elseif dojo.typeID == Constants.IDType.EquipmentDogFood then
        settingId = AutoIds.IdSetting35
        voName = "EquipmentDogFoodVo"
    else
        printError("not exist type %s", dojo.typeID)
    end
    local setting = SettingMgr:GetInstance():GetSetting(settingId, voName)
    return setting:Get(dojo.goodsId)
end

